  const w2y = Math.cos(my*0.022+t*0.35)*8 + Math.sin(mx*0.018-t*0.45)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [100+Math.sin(t*0.45+1)*60, 40+Math.cos(t*0.65+2)*40, 0.14, 3.0],
    [400+Math.cos(t*0.55+3)*70, 200+Math.sin(t*0.75+1)*50, 0.11, 2.8],
    [60+Math.sin(t*0.85+4)*50, 150+Math.cos(t*0.45+3)*60, 0.13, 2.5],
    [440+Math.cos(t*0.65+5)*40, 100+Math.sin(t*0.55+4)*45, 0.15, 3.2]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    hS += Math.sin(d*f*1.3 - t*sp*0.4 + 2.8);
  }
  const act = aS/10, inh = iS/10, har = hS/10;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1) + Math.sin(sx*0.07+t*0.6)*Math.cos(sy*0.06-t*0.5))/3 + Math.sin((sx+sy)*0.12+t*2.5)*0.15 + Math.sin((sx-sy)*0.1-t*2)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
