      const d = Math.sqrt((gx-px)**2 + (gy-py)**2);
      if (d < minD) { minD2 = minD; minD = d; }
      else if (d < minD2) { minD2 = d; }
    }
  }
  const voronoi = minD2 - minD;
  const raw = act - inh*0.6 + bg*0.25 + spiral*0.4 + har*0.15;
  const reaction = Math.tanh(raw * 2.0);
  const cellEdge = Math.exp(-voronoi * 8);
  const cellInterior = Math.sin(minD * 6.28 - t * 1.5) * 0.3;
  const blend = reaction*0.6 + cellEdge*0.2 + cellInterior*0.1 + spiral*0.1;
  const v = blend*0.5+0.5;
